@@ -296,7 +351,22 @@ export class CalAddTransaction extends CalBaseTransaction {
  * CalModifyTransaction handles modifications.
  */
 export class CalModifyTransaction extends CalBaseTransaction {
+  /**
+   * Apply an edit or move and send its notifications. If source deletion fails
+   * during a move, remove the unchanged destination copy and rethrow the source
+   * error. Preserve copies changed by other edits. Log any cleanup failure and
+   * retain the copy for cleanup on retry.
+   * Before another edit, remove unchanged copies left by failed moves for the
+   * same source item. Preserve copies changed by other edits.
+   *
+   * @returns {Promise<void>} Resolves after storage and notifications finish.
+   * @throws If the calendar edit or move fails.
+   */
   async doTransaction() {
+    const recoveryKey = JSON.stringify([this.oldItem.calendar.id, this.oldItem.id]);
+    if (pendingMoveCopies.has(recoveryKey)) {
+      await removePendingMoveCopies(recoveryKey);
+    }
     let item;
     if (this.item.calendar.id == this.oldItem.calendar.id) {
       item = await this.calendar.modifyItem(
@@ -307,8 +377,25 @@ export class CalModifyTransaction extends CalBaseTransaction {
     } else {
       this.oldCalendar = this.oldItem.calendar;
       item = await this.calendar.addItem(this.item);
+      const copy = item.clone();
+      copy.makeImmutable();
+      try {
+        await this.oldItem.calendar.deleteItem(this.oldItem);
+      } catch (error) {
+        const copies = pendingMoveCopies.get(recoveryKey) ?? new Set();
