+"use strict";
+
+const { startAxeMutationObserverInWindow } = ChromeUtils.importESModule(
+  "resource://testing-common/mail/AxeHelpers.sys.mjs"
+);
+const { CalTransactionManager } = ChromeUtils.importESModule(
+  "resource:///modules/CalTransactionManager.sys.mjs"
+);
+let browser;
+let dialog;
+let doc;
+let calendar;
+let otherCalendar;
+let axe;
+let transaction;
