+  const button = dialog.querySelector(".calendar-event-save");
+  const select = dialog.querySelector(".calendar-selector");
+  Assert.ok(!button.disabled);
+  select.focus();
+  EventUtils.synthesizeKey("KEY_Tab", {}, browser.contentWindow);
+  Assert.equal(doc.activeElement, button, "Tab reaches Save");
+  EventUtils.synthesizeKey(
+    "KEY_Tab",
+    { shiftKey: true },
+    browser.contentWindow
+  );
+  Assert.equal(
+    doc.activeElement,
+    select,
+    "Shift+Tab returns to the calendar selector"
