+  await TestUtils.waitForCondition(() => {
+    accessible = service.getAccessibleFor(button);
+    return accessible?.name == "Save";
+  });
+  Assert.equal(
+    accessible.name,
+    "Save",
+    "Screen readers receive the action name"
+  );
+  Assert.equal(accessible.role, Ci.nsIAccessibleRole.ROLE_PUSHBUTTON);
+  const closed = BrowserTestUtils.waitForEvent(dialog, "close");
+  EventUtils.synthesizeKey("KEY_Enter", {}, browser.contentWindow);
+  await closed;
+  Assert.equal((await calendar.getItem(original.id)).title, "After Save");
+  Assert.equal(dialog.draft, null, "Success clears the draft");
+  Assert.equal(
+    doc.activeElement,
+    opener,
