+add_task(
+  async function test_pendingSaveLocksRouteAndFailureKeepsFocusAndDraft() {
+    const eventA = await createEvent({ calendar, name: "A" });
+    const eventB = await createEvent({ calendar, name: "B" });
+    await edit(eventA);
+    dialog.updateDraftSection("title", { title: "A edited" });
+    const started = Promise.withResolvers();
+    const finish = Promise.withResolvers();
+    const realTransaction = transaction;
+    let calls = 0;
+    transaction = async () => {
+      calls++;
+      started.resolve();
+      await finish.promise;
+      throw new Error("Save failed");
+    };
+    registerCleanupFunction(() => {
+      transaction = realTransaction;
+      finish.resolve();
+    });
+    const button = dialog.querySelector(".calendar-event-save");
+    button.focus();
+    const pending = dialog.save();
+    await started.promise;
+    Assert.ok(button.disabled, "Save is disabled while pending");
+    const service = Cc["@mozilla.org/accessibilityService;1"].getService(
+      Ci.nsIAccessibilityService
+    );
+    let accessible;
+    await TestUtils.waitForCondition(() => {
+      accessible = service.getAccessibleFor(button);
+      if (!accessible) {
+        return false;
+      }
+      const current = {};
+      accessible.getState(current, {});
+      return current.value & Ci.nsIAccessibleStates.STATE_UNAVAILABLE;
+    }, "Speech users receive the unavailable Save state");
+
+    Assert.equal(
+      doc.activeElement,
+      dialog,
+      "Disabling Save retains focus in the dialog"
+    );
+    const body = dialog.querySelector(
+      ".calendar-event-create-edit-dialog-body"
+    );
+    Assert.equal(body.getAttribute("aria-busy"), "true");
+    Assert.equal((await dialog.save()).status, "unavailable");
+    Assert.equal(calls, 1);
+    dialog.setCalendarEventRoute({
+      calendarId: calendar.id,
+      eventId: eventB.id,
+    });
+    dialog.setAttribute("event-id", eventB.id);
+    Assert.equal(
+      dialog.getAttribute("event-id"),
+      eventA.id,
+      "Pending Save rejects route and attribute switches"
+    );
+    dialog.close();
+    Assert.ok(dialog.open, "Closing waits for Save to finish");
+    await doc.l10n.translateFragment(dialog);
+    await axe.flush();
+    finish.resolve();
+    Assert.equal((await pending).status, "error");
+    Assert.ok(dialog.open);
+    Assert.equal(dialog.draft.title, "A edited");
+    Assert.equal((await calendar.getItem(eventA.id)).title, "A");
+    Assert.equal(body.getAttribute("aria-busy"), "false");
+    Assert.ok(!button.disabled, "Failure makes Save available for retry");
+    const message = dialog.querySelector(".calendar-event-save-status");
+    Assert.equal(message.getAttribute("role"), "status");
+    Assert.equal(message.getAttribute("aria-live"), "polite");
+    let statusAccessible;
+    await TestUtils.waitForCondition(
+      () => (statusAccessible = service.getAccessibleFor(message))
+    );
+    Assert.equal(statusAccessible.role, Ci.nsIAccessibleRole.ROLE_STATUSBAR);
+    Assert.equal(
+      statusAccessible.attributes.getStringProperty("live"),
+      "polite",
+      "Screen readers receive polite status announcements"
+    );
+
+    Assert.equal(
+      doc.l10n.getAttributes(message).id,
+      "calendar-event-save-failed"
+    );
+    await doc.l10n.translateFragment(dialog);
+    Assert.ok(
+      message.textContent.includes("Try again"),
+      "Speech users receive the retry message"
+    );
+    await axe.flush();
+    transaction = realTransaction;
+    button.focus();
+    const closed = BrowserTestUtils.waitForEvent(dialog, "close");
+    EventUtils.synthesizeKey(" ", {}, browser.contentWindow);
+    await closed;
+    Assert.equal((await calendar.getItem(eventA.id)).title, "A edited");
+  }
+);
