+  await CalTransactionManager.getInstance().undo();
+  Assert.ok(await calendar.getItem(original.id));
+  Assert.equal(await otherCalendar.getItem(original.id), null);
+  await CalTransactionManager.getInstance().redo();
+  Assert.ok(await otherCalendar.getItem(original.id));
+});
