+add_task(async function test_escapeDismissesReadyAndFailedButNotPending() {
+  const original = await createEvent({ calendar, name: "Escape" });
+  const opener = doc.getElementById("menuCreate");
+  const realTransaction = transaction;
+  for (const fail of [false, true]) {
+    opener.focus();
+    await edit(original);
+    try {
+      dialog.updateDraftSection("title", { title: "Discarded by Escape" });
+      if (fail) {
+        const started = Promise.withResolvers();
+        const finish = Promise.withResolvers();
+        transaction = async () => {
+          started.resolve();
+          await finish.promise;
+          throw new Error("Save failed");
+        };
+        const pending = dialog.save();
+        try {
+          await started.promise;
+          Assert.equal(
+            dialog.closedBy,
+            "none",
+            "Pending Save disables native close requests"
+          );
+          const returnValue = dialog.returnValue;
+          dialog.requestClose("ignored");
+          Assert.ok(
+            dialog.open,
+            "A native close request waits for pending Save"
+          );
+          Assert.equal(
+            dialog.returnValue,
+            returnValue,
+            "Pending Save preserves the dialog result"
+          );
+          dialog.focus();
+          EventUtils.synthesizeKey("KEY_Escape", {}, browser.contentWindow);
+          await TestUtils.waitForTick();
+          Assert.ok(dialog.open, "Escape keeps a pending Save open");
+        } finally {
+          finish.resolve();
+          Assert.equal((await pending).status, "error");
+          transaction = realTransaction;
+        }
+      }
+      Assert.equal(dialog.closedBy, "closerequest");
+      dialog.querySelector(".calendar-event-save").focus();
+      EventUtils.synthesizeKey("KEY_Escape", {}, browser.contentWindow);
+      await TestUtils.waitForTick();
+      Assert.ok(!dialog.open, "Escape dismisses ready and failed edits");
+      Assert.equal(
+        doc.activeElement,
+        opener,
+        "Escape returns focus to the opener"
+      );
+      Assert.equal(dialog.draft, null, "Escape discards the draft");
+      Assert.equal((await calendar.getItem(original.id)).title, "Escape");
+    } finally {
+      transaction = realTransaction;
+      dialog.close();
+    }
+  }
+});
