+  );
+  const notifications = [];
+  const observer = { onModifyItem: item => notifications.push(item.title) };
+  calendar.addObserver(observer);
+  registerCleanupFunction(() => calendar.removeObserver(observer));
+  Assert.equal((await save()).status, "success");
+  Assert.equal(
