+  store.dispatch(
+    updateSection({
+      sessionKey,
+      section: "location",
+      patch: { enabledRows: { location: false }, location: "New room" },
+    })
+  );
+  const retained = JSON.stringify(
+    selectCalendarEventDraftState(store.getState(), sessionKey)
+  );
+  const fields = { location: locationField };
+  Assert.deepEqual(
+    prepareCalendarEventSave(
+      selectCalendarEventDraftState(store.getState(), sessionKey).value,
+      fields
+    ),
+    { location: { enabled: false, values: {} } },
+    "Disabled values are excluded"
+  );
+  const started = Promise.withResolvers();
+  const finish = Promise.withResolvers();
+  let calls = 0;
+  const pending = save({
+    fields,
+    transact: async event => {
+      calls++;
+      Assert.equal(
+        event.getProperty("LOCATION"),
+        null,
+        "The old property is removed from the copy"
+      );
+      started.resolve();
+      await finish.promise;
+      throw new Error("Provider failed");
+    },
+  });
+  await started.promise;
+  Assert.equal(
+    selectCalendarEventCreateEditSession(store.getState(), sessionKey).operation
+      .status,
+    "pending"
+  );
+  Assert.equal((await save()).status, "unavailable");
+  Assert.equal(calls, 1, "A duplicate Save starts no transaction");
+  finish.resolve();
+  Assert.equal((await pending).status, "error");
+  Assert.equal(
+    JSON.stringify(selectCalendarEventDraftState(store.getState(), sessionKey)),
+    retained,
+    "Failure and preparation retain row state and values"
+  );
+  Assert.equal(
+    (await calendar.getItem(original.id)).getProperty("LOCATION"),
+    "Old room"
+  );
+  Assert.equal((await save({ fields })).status, "success");
+  Assert.equal(
+    (await calendar.getItem(original.id)).getProperty("LOCATION"),
+    null
+  );
+
+  await startEdit(original);
+  store.dispatch(
+    initializeFields({
+      sessionKey,
+      defaults: { enabledRows: { location: true }, location: "Retained room" },
+    })
+  );
+  for (const enabled of [false, true]) {
+    store.dispatch(
+      updateSection({
+        sessionKey,
+        section: "location",
+        patch: {
+          enabledRows: { location: enabled },
+          location: "Retained room",
+        },
+      })
+    );
+  }
+  Assert.equal((await save({ fields })).status, "success");
+  Assert.equal(
+    (await calendar.getItem(original.id)).getProperty("LOCATION"),
+    "Retained room"
+  );
+});
