+add_task(async function test_calendarMoveQueueFailureAndCleanup() {
+  const source = {
+    calendarId: calendar.id,
+    eventId: cal.getUUID(),
+    recurrenceId: null,
+  };
+  const moved = { ...source, calendarId: destination.id };
+  const moving = queueCalendarEventEdit(source, async () => moved);
+  const started = Promise.withResolvers();
+  const finish = Promise.withResolvers();
+  let olderFinished = false;
+  const older = queueCalendarEventEdit(source, async identity => {
+    Assert.equal(identity.calendarId, destination.id);
+    started.resolve();
+    await finish.promise;
+    olderFinished = true;
+    throw new Error("provider-failure");
+  });
+  await moving;
+  await started.promise;
+  const newest = queueCalendarEventEdit(moved, async identity => {
+    Assert.ok(olderFinished, "A failed older Save still preserves queue order");
+    return identity;
+  });
+  finish.resolve();
+  await Assert.rejects(older, /provider-failure/);
+  Assert.deepEqual(await newest, moved);
+  const sourceAgain = await queueCalendarEventEdit(
+    source,
+    async identity => identity
+  );
+  Assert.deepEqual(
+    sourceAgain,
+    source,
+    "Idle queues remove the old calendar alias"
+  );
+  const destinationAgain = await queueCalendarEventEdit(
+    moved,
+    async identity => identity
+  );
+  Assert.deepEqual(
+    destinationAgain,
+    moved,
+    "Idle queues remove the destination alias"
+  );
+});
