+  const sourceProvider = calendar.wrappedJSObject;
+  const targetProvider = storage.wrappedJSObject;
+  const sourceDelete = sourceProvider.deleteItem;
+  const targetDelete = targetProvider.deleteItem;
+  const checkAndSend = cal.itip.checkAndSend;
+  const notifications = [];
+  cal.itip.checkAndSend = (...args) => notifications.push(args);
+  try {
+    for (const retry of ["move", "source", "changed-copy", "revised-copy"]) {
+      const original = await createEvent(retry == "move");
+      await startEdit(original);
+      changeTitle("Move draft");
+      store.dispatch(
+        updateSection({
+          sessionKey,
+          section: "calendar",
+          patch: { calendarId: storage.id },
+        })
+      );
+      const independent = original.clone();
+      independent.calendar = destination;
+      independent.title = "Independent calendar copy";
+      await destination.addItem(independent);
+      const undoStack = [...manager.undoStack];
+      const redoStack = [...manager.redoStack];
+      notifications.length = 0;
+      sourceProvider.deleteItem = async () => {
+        throw new Error("Source deletion failed");
+      };
+      targetProvider.deleteItem = async () => {
+        throw new Error("Destination cleanup failed");
+      };
+      Assert.equal((await save()).status, "error");
+      Assert.equal((await calendar.getItem(original.id)).title, "Original");
+      Assert.equal((await storage.getItem(original.id)).title, "Move draft");
+      Assert.deepEqual(notifications, []);
+      Assert.deepEqual(manager.undoStack, undoStack);
+      Assert.deepEqual(manager.redoStack, redoStack);
+      sourceProvider.deleteItem = sourceDelete;
+      if (retry == "move") {
+        Assert.equal(
+          (await save()).status,
+          "error",
+          "Retry waits until destination cleanup also recovers"
+        );
+        Assert.equal((await calendar.getItem(original.id)).title, "Original");
+        Assert.equal((await storage.getItem(original.id)).title, "Move draft");
+        Assert.deepEqual(notifications, []);
+        Assert.deepEqual(manager.undoStack, undoStack);
+      }
+      targetProvider.deleteItem = targetDelete;
+      if (retry == "changed-copy" || retry == "revised-copy") {
+        const oldCopy = await storage.getItem(original.id);
+        const changed = oldCopy.clone();
+        if (retry == "changed-copy") {
+          changed.title = "Another editor's copy";
+        }
+        await storage.modifyItem(changed, oldCopy);
+        Assert.equal((await saveWithDuplicateId(storage)).status, "error");
+        Assert.equal(
+          (await storage.getItem(original.id)).title,
+          changed.title,
+          "Recovery must not delete a copy with changed content or revision"
+        );
+        Assert.equal((await calendar.getItem(original.id)).title, "Original");
+        Assert.deepEqual(notifications, []);
+        Assert.deepEqual(manager.undoStack, undoStack);
+        await storage.deleteItem(await storage.getItem(original.id));
+      }
+      if (retry == "source") {
+        store.dispatch(
+          updateSection({
+            sessionKey,
+            section: "calendar",
+            patch: { calendarId: calendar.id },
+          })
+        );
+      }
+      changeTitle("Recovered draft");
+      Assert.equal((await save()).status, "success", `Retry ${retry} succeeds`);
+      Assert.equal(
+        (await destination.getItem(original.id)).title,
+        "Independent calendar copy",
+        "Recovery leaves unrelated calendar copies unchanged"
+      );
+      if (retry == "source") {
+        Assert.equal(await storage.getItem(original.id), null);
+        Assert.equal(
+          (await calendar.getItem(original.id)).title,
+          "Recovered draft"
+        );
+        Assert.deepEqual(
+          notifications.map(args => args[0]),
+          [Ci.calIOperationListener.MODIFY]
+        );
+      } else {
+        Assert.equal(await calendar.getItem(original.id), null);
+        Assert.equal(
+          (await storage.getItem(original.id)).title,
+          "Recovered draft"
+        );
+        Assert.deepEqual(
+          notifications.map(args => args[0]),
+          [Ci.calIOperationListener.ADD, Ci.calIOperationListener.DELETE]
+        );
+      }
+      await manager.undo();
+      Assert.equal((await calendar.getItem(original.id)).title, "Original");
+      Assert.equal(await storage.getItem(original.id), null);
+      await manager.redo();
+      Assert.equal(
+        (await (retry == "source" ? calendar : storage).getItem(original.id))
+          .title,
+        "Recovered draft"
+      );
+    }
+  } finally {
+    sourceProvider.deleteItem = sourceDelete;
+    targetProvider.deleteItem = targetDelete;
+    cal.itip.checkAndSend = checkAndSend;
+  }
+});
+
+add_task(async function test_moveRollbackPreservesPendingDestinationEdits() {
+  const storage = cal.manager.createCalendar(
+    "storage",
+    Services.io.newURI("moz-storage-calendar://")
+  );
+  storage.name = "Concurrent destination";
+  cal.manager.registerCalendar(storage);
+  registerCleanupFunction(() => cal.manager.unregisterCalendar(storage));
+  const sourceProvider = calendar.wrappedJSObject;
+  const sourceDelete = sourceProvider.deleteItem;
+  const checkAndSend = cal.itip.checkAndSend;
+  const notifications = [];
+  cal.itip.checkAndSend = (...args) => notifications.push(args);
+  try {
+    for (const change of ["content", "revision"]) {
+      const original = await createEvent();
+      await startEdit(original);
+      changeTitle("Move draft");
+      store.dispatch(
+        updateSection({
+          sessionKey,
+          section: "calendar",
+          patch: { calendarId: storage.id },
+        })
+      );
+      const undoStack = [...manager.undoStack];
+      const redoStack = [...manager.redoStack];
+      const started = Promise.withResolvers();
+      const finish = Promise.withResolvers();
+      const sourceError = new Error("Source deletion failed");
+      sourceProvider.deleteItem = async () => {
+        started.resolve();
+        await finish.promise;
+        throw sourceError;
+      };
+      notifications.length = 0;
+      const pending = save();
+      try {
+        await started.promise;
+        const copy = await storage.getItem(original.id);
+        const changed = copy.clone();
+        if (change == "content") {
+          changed.title = "Another editor's title";
+        }
+        const updated = await storage.modifyItem(changed, copy);
+        Assert.greater(
+          updated.generation,
+          copy.generation,
+          "The other edit advances the destination revision"
+        );
+        finish.resolve();
+        Assert.equal((await pending).status, "error");
+        let stored = await storage.getItem(original.id);
+        Assert.ok(
+          stored,
+          "Rollback preserves the destination edited while pending"
+        );
+        Assert.ok(
+          cal.item.compareContent(stored, updated, [], {}),
+          "Rollback preserves all content and revision properties"
+        );
+        Assert.equal((await calendar.getItem(original.id)).title, "Original");
+        Assert.deepEqual(notifications, []);
+        Assert.deepEqual(manager.undoStack, undoStack);
+        Assert.deepEqual(manager.redoStack, redoStack);
+        Assert.equal(
+          selectCalendarEventDraftState(store.getState(), sessionKey).value
+            .title,
+          "Move draft"
+        );
+        sourceProvider.deleteItem = sourceDelete;
+        Assert.equal(
+          (await saveWithDuplicateId(storage)).status,
+          "error",
+          "Retry cannot overwrite another editor's destination copy"
+        );
+        stored = await storage.getItem(original.id);
+        Assert.ok(cal.item.compareContent(stored, updated, [], {}));
+        Assert.deepEqual(notifications, []);
+        Assert.deepEqual(manager.undoStack, undoStack);
+        store.dispatch(
+          updateSection({
+            sessionKey,
+            section: "calendar",
+            patch: { calendarId: calendar.id },
+          })
+        );
+        Assert.equal((await save()).status, "success");
+        Assert.equal((await calendar.getItem(original.id)).title, "Move draft");
+        Assert.ok(
+          cal.item.compareContent(
+            await storage.getItem(original.id),
+            updated,
+            [],
+            {}
+          ),
+          "Changing the retained draft's calendar preserves the other edit"
+        );
+        Assert.deepEqual(
+          notifications.map(args => args[0]),
+          [Ci.calIOperationListener.MODIFY]
+        );
+        await manager.undo();
+        Assert.equal((await calendar.getItem(original.id)).title, "Original");
+        Assert.ok(
+          cal.item.compareContent(
+            await storage.getItem(original.id),
+            updated,
+            [],
+            {}
+          )
+        );
+        await manager.redo();
+        Assert.equal((await calendar.getItem(original.id)).title, "Move draft");
+        Assert.ok(
+          cal.item.compareContent(
+            await storage.getItem(original.id),
+            updated,
+            [],
+            {}
+          )
+        );
+      } finally {
+        finish.resolve();
+        await pending;
+        sourceProvider.deleteItem = sourceDelete;
+      }
+    }
+  } finally {
+    sourceProvider.deleteItem = sourceDelete;
+    cal.itip.checkAndSend = checkAndSend;
+  }
+});
